  ('LC1', 62126, 'tv', 'Hero is your word, not mine.', 'Given superstrength and durability by a sabotaged experiment, a wrongly accused man escapes prison to become a superhero for hire.', '/yzM1hMB3PUJqbISX0f421b3xOjB.jpg', '/bJOmop22SGTHPo1tiuVAFf4U7B9.jpg', '2016-09-30', 6.9, '[{"name":"Mike Colter","character":"Luke Cage","profilePath":"/9LG9AzoY2ak6M2kwhKlGkLOUUot.jpg"},{"name":"Alfre Woodard","character":"Mariah Dillard","profilePath":"/erXesg092Pi7SHKEK2UHeimPPKf.jpg"},{"name":"Simone Missick","character":"Misty Knight","profilePath":"/15IVj29u7NJgRoVnulCgbb9c8FA.jpg"},{"name":"Theo Rossi","character":"Hernan ‘Shades’ Alvarez","profilePath":"/344QE41Jileu4OE41cmYgBxc5BF.jpg"},{"name":"Mustafa Shakir","character":"John ''Bushmaster'' McIver","profilePath":"/eeBtCxmlmHguKbeUr2Usx2Jdnj9.jpg"},{"name":"Gabrielle Dennis","character":"Tilda Johnson","profilePath":"/rKhkx7aBAlGegA87JNedmhziUTN.jpg"}]'::jsonb, 'https://www.themoviedb.org/tv/62126-marvel-s-luke-cage/watch?locale=IN'),
