  ('DEF', 11515, 'tv', null, 'The Defenders is an American courtroom drama series . It starred E. G. Marshall and Robert Reed as father-and-son defense attorneys who specialized in legally complex cases, with defendants such as neo-Nazis, conscientious objectors, civil rights demonstrators, a schoolteacher fired for being an atheist, an author accused of pornography, and a physician charged in a mercy killing.', '/g4QCPffsJqElwCu8f1JvvuaRVsc.jpg', '/8kX9xQPQGOpA8tQX5SS2IxEk544.jpg', '1961-09-16', 6.3, '[{"name":"E.G. Marshall","character":"Lawrence Preston","profilePath":"/psimeVoRk64DV7UNm4cLQylRFy2.jpg"},{"name":"Robert Reed","character":"Kenneth Preston","profilePath":"/49pP5rwAWVj3hpHwAf5bxtE1dom.jpg"}]'::jsonb, null),
