  ('IRH', 114471, 'tv', 'Every dream has a cost.', 'After the events of Black Panther: Wakanda Forever, technology is pitted against magic when Riri Williams, a young, genius inventor determined to make her mark on the world, returns to her hometown of Chicago. Her unique take on building iron suits is brilliant, but in pursuit of her ambitions, she finds herself wrapped up with the mysterious yet charming Parker Robbins aka "The Hood."', '/dOh6MJpdlQhYpLBhzhNQeYGKTZ5.jpg', '/kiOEVg5BkzLE0pWoPKecXd7wZ2Q.jpg', '2025-06-24', 5.3, '[{"name":"Dominique Thorne","character":"Riri Williams","profilePath":"/tuLlp79SfYc4mLzzjdC2ekLI7qd.jpg"},{"name":"Lyric Ross","character":"N.A.T.A.L.I.E.","profilePath":"/sRh8aD95pBYpt2LDR1OWs2DwDbf.jpg"},{"name":"Manny Montana","character":"Cousin John","profilePath":"/EUoD5EalyUDHZtRZCnosRqhMi.jpg"},{"name":"Matthew Elam","character":"Xavier","profilePath":"/vYV8zfLEFOiOXTXoHfF1oEmwbYG.jpg"},{"name":"Anji White","character":"Ronnie Williams","profilePath":"/6JcZUdPQ3sz35g4N6JDarfRnPOo.jpg"},{"name":"Eric André","character":"Rampage","profilePath":"/e9XlcFnZQiBSQ1vISQVyTOrkIaq.jpg"},{"name":"Sonia Denis","character":"Clown","profilePath":"/rWxTssmmEX3tkMArKVSpdETlLTV.jpg"},{"name":"Shea Couleé","character":"Slug","profilePath":"/bB1TYBavSXYv04WW66PrQmlG4Uk.jpg"}]'::jsonb, 'https://www.themoviedb.org/tv/114471-ironheart/watch?locale=IN'),
